#!/usr/bin/env bash
set -euo pipefail

dev_browser_base="/root/.dev-browser"
dev_browser_socket="$dev_browser_base/daemon.sock"
dev_browser_pid_file="$dev_browser_base/daemon.pid"
dev_browser_runtime="/usr/lib/node_modules/dev-browser/daemon/dist/daemon.bundle.mjs"
dev_browser_native="/usr/lib/node_modules/dev-browser/bin/dev-browser-linux-x64"
dev_browser_chromium="/root/.cache/ms-playwright/chromium-1200/chrome-linux64/chrome"

daemon_is_running() {
  [[ -S "$dev_browser_socket" && -f "$dev_browser_pid_file" ]] || return 1
  local daemon_pid
  daemon_pid="$(tr -d '[:space:]' < "$dev_browser_pid_file")"
  [[ "$daemon_pid" =~ ^[0-9]+$ ]] && kill -0 "$daemon_pid" 2>/dev/null
}

if [[ " ${*:-} " == *" status "* || " ${*:-} " == *" browsers "* || " ${*:-} " == *" stop "* || " ${*:-} " == *" install "* ]]; then
  exec "$dev_browser_native" "$@"
fi

# A long-lived shared Chromium can wedge (a looping tab blocks CDP attach, and
# every client then times out). Restart it when it stops answering /json/list
# quickly or has piled up tabs.
if curl -fsS -m 2 http://127.0.0.1:9222/json/version >/dev/null 2>&1; then
  tab_count="$(curl -fsS -m 3 http://127.0.0.1:9222/json/list 2>/dev/null | grep -c '"type": "page"' || true)"
  if [[ -z "$tab_count" || "$tab_count" -gt 12 ]]; then
    chromium_pid="$(ss -ltnp 2>/dev/null | grep ':9222 ' | grep -o 'pid=[0-9]*' | head -1 | cut -d= -f2)"
    if [[ -n "$chromium_pid" ]]; then
      kill "$chromium_pid" 2>/dev/null || true
      for _ in {1..40}; do
        curl -fsS -m 1 http://127.0.0.1:9222/json/version >/dev/null 2>&1 || break
        sleep 0.1
      done
    fi
  fi
fi

if ! curl -fsS http://127.0.0.1:9222/json/version >/dev/null 2>&1; then
  mkdir -p "$dev_browser_base/browsers/cdp-profile"
  setsid -f "$dev_browser_chromium" --headless=new --no-sandbox --disable-dev-shm-usage \
    --remote-debugging-port=9222 --user-data-dir="$dev_browser_base/browsers/cdp-profile" about:blank \
    >>"$dev_browser_base/chromium.log" 2>&1 </dev/null
  for _ in {1..100}; do
    curl -fsS http://127.0.0.1:9222/json/version >/dev/null 2>&1 && break
    sleep 0.05
  done
fi

runner_args=()
for arg in "$@"; do [[ "$arg" == "run" || -f "$arg" ]] && runner_args+=("$arg"); done
exec node /root/.local/lib/dev-browser-local.mjs "${runner_args[@]}"

